from math import exp, log
from typing import Sequence

def audit(q: Sequence[float], p: Sequence[float], a: Sequence[float]) -> dict[str, float]:
    if not (len(q) == len(p) == len(a)) or not q:
        raise ValueError("inputs must be nonempty and equally long")
    if any(x <= 0 for x in q) or any(x <= 0 for x in p):
        raise ValueError("masses must be positive")
    if abs(sum(q)-1) > 1e-10 or abs(sum(p)-1) > 1e-10:
        raise ValueError("distributions must sum to one")
    z = sum(pi*exp(ai) for pi,ai in zip(p,a))
    lhs = sum(qi*ai for qi,ai in zip(q,a))
    kl = sum(qi*log(qi/pi) for qi,pi in zip(q,p))
    return {"expectation": lhs, "upper_bound": kl+log(z), "slack": kl+log(z)-lhs}

if __name__ == "__main__":
    print(audit((.2,.35,.45),(.5,.3,.2),(-.25,.6,1.1)))

from math import log, sqrt

def gaussian_kl(d: int, norm_w: float, sigma_q: float, sigma_p: float) -> float:
    if d < 0 or sigma_q <= 0 or sigma_p <= 0:
        raise ValueError("invalid Gaussian parameters")
    x = sigma_q**2/sigma_p**2
    return norm_w**2/(2*sigma_p**2) + d/2*(x-1-log(x))

def certificate(d: int, norm_w: float, sigma_q: float, sigma_p: float, empirical: float, n: int, delta: float) -> tuple[float,float]:
    if n <= 1 or not 0 < delta < 1:
        raise ValueError("require n > 1 and 0 < delta < 1")
    kl=gaussian_kl(d,norm_w,sigma_q,sigma_p)
    bound=empirical+sqrt((kl+log(2*sqrt(n)/delta))/(2*(n-1)))
    return kl,bound

if __name__ == "__main__":
    for n in (100,1000,10000): print(n, certificate(50,2,1,1,.08,n,.05))

from math import exp, log
from typing import Iterable

def catoni(empirical: float, kl: float, n: int, delta: float, lam: float) -> float:
    if n <= 0 or not 0 < delta < 1 or lam <= 0:
        raise ValueError("invalid domain")
    return (1-exp(-lam*empirical-(kl+log(1/delta))/n))/(1-exp(-lam))

def grid_search(empirical: float, kl: float, n: int, delta: float, grid: Iterable[float]) -> tuple[float,float]:
    values=[(catoni(empirical,kl,n,delta,x),x) for x in grid]
    if not values: raise ValueError("empty grid")
    value,lam=min(values)
    return lam,value

if __name__ == "__main__": print(grid_search(.1,1.125,2000,.05,(.05,.1,.2,.5,1,2,5)))

